tencyHash" text NOT NULL UNIQUE,"intentHash" text NOT NULL,"expiresAt" timestamptz NOT NULL,"successAuditEventId" uuid NOT NULL REFERENCES public.audit_events("id") ON DELETE RESTRICT,CONSTRAINT "f1_p10_consent_action_check" CHECK("action" IN('granted','updated','withdrawn')));CREATE TABLE public.f1_p02_resolver_registry ("resourceType" text PRIMARY KEY,"resolverId" text NOT NULL UNIQUE,"tableName" text NOT NULL,"idSemantics" text NOT NULL,"operationKey" text NOT NULL,"permissionKey" text NOT NULL,CONSTRAINT "f1_p02_resolver_registry_closed_check" CHECK (("resourceType","resolverId","tableName","idSemantics","operationKey","permissionKey") IN (('p08_import','resolver.p08_import','dashboard_import_batch','uuid','read','dashboard.import.foundation_sample.read'),('p08_export','resolver.p08_export','dashboard_export_request','uuid','read','dashboard.export.foundation_sample.read'),('p09_config','resolver.p09_config','runtime_config_version','row_uuid','read','config.read'),('p09_flag','resolver.p09_flag','feature_flag_version','row_uuid','read','flags.read'),('p09_readiness_summary','resolver.p09_readiness_summary','worker_heartbeats','literal:worker-fleet','read','readiness.read_summary'),('p09_readiness_detail','resolver.p09_readiness_detail','worker_heartbeats','literal:worker-fleet','read','readiness.read_detail'),('p10_analytics_ingestion','resolver.p10_analytics_ingestion','foundation_sample','uuid','ingest','analytics.ingest'),('p10_release_family','resolver.p10_release_family','analytics_foundation_release','six-field-family','read','analytics.release.read'))));INSERT INTO public.f1_p02_resolver_registry VALUES ('p08_import','resolver.p08_import','dashboard_import_batch','uuid','read','dashboard.import.foundation_sample.read'),('p08_export','resolver.p08_export','dashboard_export_request','uuid','read','dashboard.export.foundation_sample.read'),('p09_config','resolver.p09_config','runtime_config_version','row_uuid','read','config.read'),('p09_flag','resolver.p09